def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where BOTH values are dictionaries; treats all other values atomically.
    If a key is added or removed entirely, only that key's path is returned.
    """
    results = set()

    def _recurse(prefix, b, a):
        for key in set(b) | set(a):
            path = f"{prefix}.{key}" if prefix else key
            if key not in b:
                results.add(path)
            elif key not in a:
                results.add(path)
            else:
                bv = b[key]
                av = a[key]
                if isinstance(bv, dict) and isinstance(av, dict):
                    _recurse(path, bv, av)
                elif bv != av:
                    results.add(path)

    _recurse("", before, after)
    return sorted(results)
```

