def coalesce(intervals):
    """Merge overlapping or touching half-open integer intervals.

    Args:
        intervals: iterable of (start, end) tuples representing [start, end).

    Returns:
        A sorted list of merged (start, end) tuples.

    Raises:
        ValueError: if any interval has start > end.
    """
    valid = []
    for start, end in intervals:
        if start > end:
            raise ValueError(
                f"Invalid interval ({start}, {end}): start > end"
            )
        if start < end:
            valid.append((start, end))

    if not valid:
        return []

    valid.sort()

    merged = [valid[0]]
    for start, end in valid[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged
```

