def unique_latest(records):
    first_order = []
    best = {}

    for i, rec in enumerate(records):
        rid = rec["id"]
        ts = rec["timestamp"]

        if rid not in best:
            first_order.append(rid)
            best[rid] = (ts, i, rec)
        else:
            old_ts = best[rid][0]
            if ts >= old_ts:
                best[rid] = (ts, i, rec)

    return [best[rid][2] for rid in first_order]
