def flatten(value):
    if not isinstance(value, dict):
        return value

    if len(value) == 0:
        return {}

    result = {}
    for key, val in value.items():
        if isinstance(val, dict) and len(val) > 0:
            sub = flatten(val)
            for k, v in sub.items():
                result[f"{key}.{k}"] = v
        else:
            result[key] = val
    return result
