def normalize(path: str) -> str:
    """
    Normalize an absolute POSIX-like path.

    - Raises ValueError if the path is not absolute (doesn't start with '/').
    - Collapses repeated slashes.
    - Ignores '.' components.
    - Resolves '..' components without going above root.
    - Returns '/' for the root directory.
    - Never returns a trailing slash (except root is just '/').
    - No filesystem access is performed.
    """
    if not path.startswith("/"):
        raise ValueError(f"Path must be absolute: {path!r}")

    parts = path.split("/")
    stack: list[str] = []

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
            # else: already at root, ignore
        else:
            stack.append(part)

    if not stack:
        return "/"
    return "/" + "/".join(stack)
```

