def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")
    if not items:
        return []

    byte_lengths = [len(s.encode("utf-8")) for s in items]
    for i, bl in enumerate(byte_lengths):
        if bl > max_bytes:
            raise ValueError(
                f"Item {i} has UTF-8 byte length {bl}, exceeds max_bytes {max_bytes}"
            )

    result = []
    current = []
    total = 0

    for s, bl in zip(items, byte_lengths):
        if total + bl <= max_bytes:
            current.append(s)
            total += bl
        else:
            result.append(current)
            current = [s]
            total = bl

    result.append(current)
    return result
