from collections import defaultdict


def order(deps):
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    in_degree = {}
    for node in nodes:
        in_degree[node] = len(deps.get(node, ()))

    dependents = defaultdict(list)
    for node, prereqs in deps.items():
        for p in prereqs:
            dependents[p].append(node)

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
