def redact(value, sensitive):
    sensitive_lower = {s.lower() for s in sensitive}

    def _redact(val):
        if isinstance(val, dict):
            result = {}
            for k, v in val.items():
                if isinstance(k, str) and k.lower() in sensitive_lower:
                    result[k] = "[REDACTED]"
                else:
                    result[k] = _redact(v)
            return result
        elif isinstance(val, list):
            return [_redact(item) for item in val]
        else:
            return val

    return _redact(value)
